/* =========================================================
   HE RESTORES — Core Interaction Engine
   Lenis + GSAP + ScrollTrigger + SplitType + Swiper
   ========================================================= */

(function(){
  "use strict";

  gsap.registerPlugin(ScrollTrigger);

  /* ---------------------------------------------------
     1. LENIS SMOOTH SCROLL + GSAP TICKER SYNC
  --------------------------------------------------- */
  const lenis = new Lenis({
    duration: 1.15,
    easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
    smoothWheel: true,
    wheelMultiplier: 1,
    touchMultiplier: 1.4,
  });
  lenis.on('scroll', ScrollTrigger.update);
  gsap.ticker.add((time) => { lenis.raf(time * 1000); });
  gsap.ticker.lagSmoothing(0);
  window.__lenis = lenis;

  /* ---------------------------------------------------
     2. PRELOADER + HERO ENTRANCE — ONE CONTINUOUS TIMELINE
     (preparation happens up front; every visual step —
     counter, wordmark, curtain wipe, nav, hero/page-hero
     reveal — lives on the SAME gsap.timeline instance)
  --------------------------------------------------- */
  function runIntroTimeline(){
    const preloader = document.getElementById('preloader');
    const navEl = document.querySelector('.site-header');
    const heroEyebrow = document.querySelector('.hero-copy .eyebrow, .page-hero .eyebrow');
    const heroKicker = document.querySelector('.hero-kicker');
    const heroBadge = document.querySelector('.hero-badge');
    const heroBlob = document.querySelector('.hero-blob');
    const heroHeading = document.querySelector('.hero-copy h1, .page-hero h1');
    const heroSub = document.querySelector('.hero-copy .sub, .page-hero .sub');
    const heroBtns = document.querySelector('.hero-copy .btn-row');
    const heroBook = document.querySelector('.hero-book img');
    const heroMedia = document.querySelector('.page-hero .ph-media');
    const crumb = document.querySelector('.crumb');

    /* -- pre-split hero heading & set start states before timeline runs -- */
    let headingSplit = null;
    if(heroHeading){
      headingSplit = new SplitType(heroHeading, { types: 'lines,words' });
      gsap.set(headingSplit.words, { yPercent: 120, opacity: 0 });
    }
    if(heroEyebrow) gsap.set(heroEyebrow, { opacity: 0, x: -20 });
    if(heroKicker) gsap.set(heroKicker, { opacity: 0, y: -10 });
    if(heroBadge) gsap.set(heroBadge, { opacity: 0, scale: 0.5, rotate: -20 });
    if(heroBlob) gsap.set(heroBlob, { opacity: 0, scale: 0.7 });
    if(crumb) gsap.set(crumb, { opacity: 0, x: -20 });
    if(heroSub) gsap.set(heroSub, { opacity: 0, y: 20 });
    if(heroBtns) gsap.set(heroBtns.children, { opacity: 0, y: 16 });
    if(heroBook) gsap.set(heroBook, { opacity: 0, scale: 0.86, rotateY: 18 });
    if(heroMedia) gsap.set(heroMedia, { opacity: 0, scale: 0.92, y: 24 });
    if(navEl) gsap.set(navEl, { y: -30, opacity: 0 });

    const tl = gsap.timeline({
      onComplete: () => { lenis.start(); document.body.classList.add('is-ready'); ScrollTrigger.refresh(); }
    });

    if(!preloader){
      // no preloader present on this render — just play the entrance directly
      tl.to(navEl || {}, { y: 0, opacity: 1, duration: 0.7, ease: 'power3.out' }, 0);
    } else {
      const wordEl = preloader.querySelector('.pl-word');
      const bar = preloader.querySelector('.pl-bar');
      const pct = preloader.querySelector('.pl-pct');
      const curtainL = document.getElementById('pl-curtain-l');
      const curtainR = document.getElementById('pl-curtain-r');

      if(wordEl){
        const text = wordEl.textContent;
        wordEl.innerHTML = '';
        text.split('').forEach(ch=>{
          const span = document.createElement('span');
          span.className = 'char';
          span.textContent = ch === ' ' ? '\u00A0' : ch;
          wordEl.appendChild(span);
        });
      }

      const counter = { val: 0 };

      /* --- Step 1: counting bar + wordmark reveal --- */
      tl.to(counter, {
        val: 100, duration: 1.0, ease: 'power2.inOut',
        onUpdate: () => {
          if(bar) bar.style.width = counter.val + '%';
          if(pct) pct.textContent = Math.floor(counter.val) + '%';
        }
      }, 0)
      .to(wordEl ? wordEl.querySelectorAll('.char') : [], {
        opacity: 1, stagger: 0.028, duration: 0.35, ease: 'power2.out'
      }, 0.05)
      /* --- Step 2: preloader fade out --- */
      .to(preloader.querySelectorAll('.pl-bar-wrap, .pl-pct'), { opacity: 0, duration: 0.25 }, '-=0.2')
      .to(wordEl, { opacity: 0, y: -20, duration: 0.3, ease: 'power2.in' }, '-=0.1')
      /* --- Step 3: curtain wipe reveals the page --- */
      .set([curtainL, curtainR], { display: 'block' })
      .set(preloader, { display: 'none' })
      .fromTo(curtainL, { xPercent: 0 }, { xPercent: -100, duration: 0.7, ease: 'power4.inOut' }, '+=0.02')
      .fromTo(curtainR, { xPercent: 0 }, { xPercent: 100, duration: 0.7, ease: 'power4.inOut' }, '<')
      .set([curtainL, curtainR], { display: 'none' })
      /* --- Step 4: nav + hero/page-hero entrance, same timeline, heavy overlap with wipe --- */
      .to(navEl || {}, { y: 0, opacity: 1, duration: 0.6, ease: 'power3.out' }, '-=0.55');
    }

    /* -- hero / page-hero content block continues on the SAME tl, overlapping the curtain wipe so it feels instant -- */
    const contentStart = preloader ? '-=0.6' : 0.1;
    if(heroEyebrow) tl.to(heroEyebrow, { opacity: 1, x: 0, duration: 0.5, ease: 'power2.out' }, contentStart);
    if(heroKicker) tl.to(heroKicker, { opacity: 1, y: 0, duration: 0.5, ease: 'power2.out' }, contentStart);
    if(heroBlob) tl.to(heroBlob, { opacity: 1, scale: 1, duration: 1.1, ease: 'power2.out' }, contentStart);
    if(heroBadge) tl.to(heroBadge, { opacity: 1, scale: 1, rotate: 10, duration: 0.7, ease: 'back.out(1.7)' }, contentStart + '+=0.28');
    if(crumb) tl.to(crumb, { opacity: 1, x: 0, duration: 0.5, ease: 'power2.out' }, contentStart);
    if(headingSplit) tl.to(headingSplit.words, { yPercent: 0, opacity: 1, duration: 0.8, stagger: 0.022, ease: 'power4.out' }, contentStart + '+=0.06');
    if(heroSub) tl.to(heroSub, { opacity: 1, y: 0, duration: 0.6, ease: 'power2.out' }, contentStart + '+=0.22');
    if(heroBtns) tl.to(heroBtns.children, { opacity: 1, y: 0, duration: 0.5, stagger: 0.08, ease: 'power2.out' }, contentStart + '+=0.35');
    if(heroBook) tl.to(heroBook, { opacity: 1, scale: 1, rotateY: 0, duration: 0.9, ease: 'power3.out' }, contentStart + '+=0.1');
    if(heroMedia) tl.to(heroMedia, { opacity: 1, scale: 1, y: 0, duration: 0.8, ease: 'power3.out' }, contentStart + '+=0.06');
  }

  document.addEventListener('DOMContentLoaded', () => {
    runIntroTimeline();
    initNav();
    initCursor();
    initReveals();
    initMagnetic();
    initJourney();
    initFaq();
    initSwipers();
    initParallaxImages();
    initThemeCards();
    initVideoModal();
    initGalleryCaptions();
  });

  /* ---------------------------------------------------
     3. NAV — scroll state + Awwwards mega menu (GSAP)
  --------------------------------------------------- */
  function initNav(){
    const header = document.querySelector('.site-header');
    if(header){
      ScrollTrigger.create({
        start: 'top -80', end: 99999,
        onUpdate: (self) => { header.classList.toggle('scrolled', self.scroll() > 80); }
      });
    }

    const burger = document.querySelector('.hamburger');
    const navToggleBtn = document.getElementById('navToggle') || burger;
    const mobileNav = document.querySelector('.mobile-nav');
    const navLinks = document.querySelectorAll('.mega-nav-links a');
    const navVisual = document.querySelector('.mega-nav-visual');
    let isOpen = false;
    let hasAnimatedIn = false;

    if(navLinks.length){ gsap.set(navLinks, { y: 0 }); }

    function openMenu(){
      isOpen = true;
      mobileNav.classList.add('open');
      if(header){ header.classList.add('nav-open'); }
      burger.classList.add('active');
      lenis.stop();
      document.querySelector('.cursor-ring')?.classList.add('on-dark');

      const tl = gsap.timeline();
      if(!hasAnimatedIn){
        tl.set(navLinks, { yPercent: 110 })
          .set(navVisual, { opacity: 0, y: 20 });
      }
      tl.to(navLinks, { yPercent: 0, duration: 0.9, stagger: 0.06, ease: 'power4.out' }, 0.15)
        .to(navVisual, { opacity: 1, y: 0, duration: 0.9, ease: 'power3.out' }, 0.35);
      hasAnimatedIn = true;
    }

    function closeMenu(){
      isOpen = false;
      mobileNav.classList.remove('open');
      if(header){ header.classList.remove('nav-open'); }
      burger.classList.remove('active');
      lenis.start();
      document.querySelector('.cursor-ring')?.classList.remove('on-dark');
    }

    if(burger && mobileNav && navToggleBtn){
      navToggleBtn.addEventListener('click', () => { isOpen ? closeMenu() : openMenu(); });
      mobileNav.querySelectorAll('a').forEach(a=>{
        a.addEventListener('click', closeMenu);
      });
      document.addEventListener('keydown', (e)=>{ if(e.key === 'Escape' && isOpen) closeMenu(); });
    }
  }

  /* ---------------------------------------------------
     4. CUSTOM CURSOR
  --------------------------------------------------- */
  function initCursor(){
    if(window.matchMedia('(hover: none)').matches) return;
    const dot = document.querySelector('.cursor-dot');
    const ring = document.querySelector('.cursor-ring');
    if(!dot || !ring) return;

    let mx=0,my=0, rx=0, ry=0;
    window.addEventListener('mousemove', (e)=>{
      mx = e.clientX; my = e.clientY;
      gsap.to(dot, { x: mx, y: my, duration: 0.1 });
    });
    gsap.ticker.add(()=>{
      rx += (mx - rx) * 0.14;
      ry += (my - ry) * 0.14;
      gsap.set(ring, { x: rx, y: ry });
    });

    document.querySelectorAll('a, button, .magnetic, input, textarea, .faq-q, .gitem').forEach(el=>{
      el.addEventListener('mouseenter', ()=> ring.classList.add('hovered'));
      el.addEventListener('mouseleave', ()=> ring.classList.remove('hovered'));
    });
  }

  /* ---------------------------------------------------
     5. SCROLL REVEALS (generic)
  --------------------------------------------------- */
  function initReveals(){
    gsap.utils.toArray('.reveal').forEach((el)=>{
      gsap.to(el, { opacity: 1, y: 0, duration: 1, ease: 'power3.out',
        scrollTrigger: { trigger: el, start: 'top 88%' } });
    });
    gsap.utils.toArray('.reveal-fade').forEach((el)=>{
      gsap.to(el, { opacity: 1, duration: 1.1, ease: 'power2.out',
        scrollTrigger: { trigger: el, start: 'top 90%' } });
    });
    gsap.utils.toArray('.reveal-scale').forEach((el)=>{
      gsap.to(el, { opacity: 1, scale: 1, duration: 1.1, ease: 'power3.out',
        scrollTrigger: { trigger: el, start: 'top 88%' } });
    });
    gsap.utils.toArray('[data-stagger]').forEach((group)=>{
      const items = group.children;
      gsap.set(items, { opacity: 0, y: 30 });
      gsap.to(items, { opacity: 1, y: 0, duration: 0.9, stagger: 0.12, ease: 'power3.out',
        scrollTrigger: { trigger: group, start: 'top 85%' } });
    });
    gsap.utils.toArray('.split-on-scroll').forEach((el)=>{
      const split = new SplitType(el, { types: 'lines,words' });
      gsap.set(split.words, { yPercent: 110, opacity: 0 });
      gsap.to(split.words, { yPercent: 0, opacity: 1, duration: 0.9, stagger: 0.03, ease: 'power4.out',
        scrollTrigger: { trigger: el, start: 'top 85%' } });
    });
  }

  /* ---------------------------------------------------
     6. MAGNETIC BUTTONS
  --------------------------------------------------- */
  function initMagnetic(){
    if(window.matchMedia('(hover: none)').matches) return;
    document.querySelectorAll('.magnetic').forEach((el)=>{
      el.addEventListener('mousemove', (e)=>{
        const r = el.getBoundingClientRect();
        const x = e.clientX - r.left - r.width/2;
        const y = e.clientY - r.top - r.height/2;
        gsap.to(el, { x: x*0.35, y: y*0.45, duration: 0.4, ease: 'power2.out' });
      });
      el.addEventListener('mouseleave', ()=>{
        gsap.to(el, { x:0, y:0, duration: 0.6, ease: 'elastic.out(1,0.4)' });
      });
    });
  }

  /* ---------------------------------------------------
     7. JOURNEY TIMELINE — scroll-driven fill + active step
  --------------------------------------------------- */
  function initJourney(){
    const track = document.querySelector('.journey-track');
    const fill = document.querySelector('.journey-line-fill');
    if(!track || !fill) return;
    const steps = gsap.utils.toArray('.journey-step');

    gsap.to(fill, { height: '100%', ease: 'none',
      scrollTrigger: { trigger: track, start: 'top 60%', end: 'bottom 70%', scrub: 0.6 } });

    steps.forEach((step)=>{
      ScrollTrigger.create({
        trigger: step, start: 'top 55%', end: 'bottom 55%',
        onEnter: ()=> step.classList.add('is-active'),
        onEnterBack: ()=> step.classList.add('is-active'),
        onLeave: ()=> step.classList.remove('is-active'),
        onLeaveBack: ()=> step.classList.remove('is-active'),
      });
      gsap.from(step, { opacity: 0, x: -24, duration: 0.9, ease: 'power3.out',
        scrollTrigger: { trigger: step, start: 'top 88%' } });
    });
  }

  /* ---------------------------------------------------
     8. THEME / CHAR / REVIEW CARD ENTRANCE
  --------------------------------------------------- */
  function initThemeCards(){
    gsap.utils.toArray('.theme-card').forEach((card, i)=>{
      gsap.from(card, { opacity: 0, y: 40, duration: 0.8, ease: 'power3.out', delay: (i%5)*0.06,
        scrollTrigger: { trigger: card, start: 'top 92%' } });
    });
  }

  /* ---------------------------------------------------
     9. FAQ ACCORDION
  --------------------------------------------------- */
  function initFaq(){
    document.querySelectorAll('.faq-item').forEach((item)=>{
      const q = item.querySelector('.faq-q');
      const a = item.querySelector('.faq-a');
      if(!q || !a) return;
      q.addEventListener('click', ()=>{
        const isOpenNow = item.classList.contains('open');
        document.querySelectorAll('.faq-item.open').forEach((openItem)=>{
          if(openItem !== item){
            openItem.classList.remove('open');
            gsap.to(openItem.querySelector('.faq-a'), { height: 0, duration: 0.5, ease: 'power2.inOut' });
          }
        });
        if(isOpenNow){
          item.classList.remove('open');
          gsap.to(a, { height: 0, duration: 0.5, ease: 'power2.inOut' });
        } else {
          item.classList.add('open');
          gsap.set(a, { height: 'auto' });
          const h = a.offsetHeight;
          gsap.fromTo(a, { height: 0 }, { height: h, duration: 0.5, ease: 'power2.inOut' });
        }
      });
    });
  }

  /* ---------------------------------------------------
     10. SWIPER — Characters & Reviews (Awwwards drag sliders)
  --------------------------------------------------- */
  function initSwipers(){
    if(typeof Swiper === 'undefined') return;

    const charEl = document.querySelector('.char-swiper');
    if(charEl){
      const s = new Swiper(charEl, {
        slidesPerView: 'auto',
        spaceBetween: 26,
        grabCursor: true,
        speed: 700,
        navigation: { nextEl: '#charNext', prevEl: '#charPrev' },
        on: {
          progress: function(sw){
            const bar = document.querySelector('#charProgress .bar');
            if(bar) bar.style.width = (sw.progress * 100) + '%';
          }
        }
      });
    }

    const reviewEl = document.querySelector('.review-swiper');
    if(reviewEl){
      const s2 = new Swiper(reviewEl, {
        slidesPerView: 'auto',
        spaceBetween: 26,
        grabCursor: true,
        speed: 700,
        navigation: { nextEl: '#reviewNext', prevEl: '#reviewPrev' },
        on: {
          progress: function(sw){
            const bar = document.querySelector('#reviewProgress .bar');
            if(bar) bar.style.width = (sw.progress * 100) + '%';
          }
        }
      });
    }
  }

  /* ---------------------------------------------------
     11. PARALLAX IMAGES + hero book tilt
  --------------------------------------------------- */
  function initParallaxImages(){
    gsap.utils.toArray('[data-parallax]').forEach((el)=>{
      gsap.to(el, { yPercent: 12, ease: 'none',
        scrollTrigger: { trigger: el.parentElement, start: 'top bottom', end: 'bottom top', scrub: true } });
    });

    const heroBook = document.querySelector('.hero-book img');
    const heroBookWrap = document.querySelector('.hero-book');
    if(heroBook && heroBookWrap && !window.matchMedia('(hover: none)').matches){
      heroBookWrap.addEventListener('mousemove', (e)=>{
        const r = heroBookWrap.getBoundingClientRect();
        const px = (e.clientX - r.left)/r.width - 0.5;
        const py = (e.clientY - r.top)/r.height - 0.5;
        gsap.to(heroBook, { rotateY: px*18, rotateX: -py*14, duration: 0.6, ease: 'power2.out' });
      });
      heroBookWrap.addEventListener('mouseleave', ()=>{
        gsap.to(heroBook, { rotateY: 0, rotateX: 0, duration: 0.8, ease: 'power3.out' });
      });
    }
  }

  /* ---------------------------------------------------
     12. VIDEO LIGHTBOX
  --------------------------------------------------- */
  function initVideoModal(){
    const modal = document.getElementById('videoModal');
    const playBtns = document.querySelectorAll('.play-btn, [data-video-trigger]');
    if(!modal || !playBtns.length) return;
    const video = modal.querySelector('video');
    const closeBtn = modal.querySelector('.vm-close');

    function open(){
      modal.classList.add('open');
      lenis.stop();
      if(video){ video.currentTime = 0; video.play().catch(()=>{}); }
    }
    function close(){
      modal.classList.remove('open');
      lenis.start();
      if(video){ video.pause(); }
    }
    playBtns.forEach(btn => btn.addEventListener('click', (e)=>{ e.preventDefault(); open(); }));
    if(closeBtn) closeBtn.addEventListener('click', close);
    modal.addEventListener('click', (e)=>{ if(e.target === modal) close(); });
    document.addEventListener('keydown', (e)=>{ if(e.key === 'Escape') close(); });
  }

  /* ---------------------------------------------------
     13. GALLERY — staggered reveal + click-to-expand lightbox
  --------------------------------------------------- */
  function initGalleryCaptions(){
    const items = document.querySelectorAll('.gallery-grid .gitem');
    if(!items.length) return;

    items.forEach((item, i)=>{
      const img = item.querySelector('img');

      /* --- Awwwards-style clip wipe reveal, cascading by column --- */
      gsap.set(item, { clipPath: 'inset(0% 0% 100% 0%)' });
      if(img) gsap.set(img, { scale: 1.12 });
      gsap.to(item, {
        clipPath: 'inset(0% 0% 0% 0%)', duration: 1.1, ease: 'power4.out', delay: (i % 4) * 0.08,
        scrollTrigger: { trigger: item, start: 'top 90%' }
      });
      if(img){
        gsap.to(img, {
          scale: 1, duration: 1.3, ease: 'power3.out', delay: (i % 4) * 0.08,
          scrollTrigger: { trigger: item, start: 'top 90%' }
        });
        /* --- continuous scroll parallax drift inside the frame --- */
        gsap.fromTo(img, { yPercent: -5 }, {
          yPercent: 5, ease: 'none',
          scrollTrigger: { trigger: item, start: 'top bottom', end: 'bottom top', scrub: 0.6 }
        });
        /* --- hover zoom, composited by GSAP alongside the parallax tween --- */
        if(!window.matchMedia('(hover: none)').matches){
          item.addEventListener('mouseenter', ()=> gsap.to(img, { scale: 1.08, duration: 0.7, ease: 'power3.out' }));
          item.addEventListener('mouseleave', ()=> gsap.to(img, { scale: 1, duration: 0.7, ease: 'power3.out' }));
        }
      }
    });

    const modal = document.getElementById('imgLightbox');
    if(!modal) return;
    const lbImg = modal.querySelector('img');
    const closeBtn = modal.querySelector('.lb-close');

    function open(src, alt){
      lbImg.src = src;
      lbImg.alt = alt || '';
      modal.classList.add('open');
      lenis.stop();
      gsap.fromTo(modal.querySelector('.lb-inner'), { scale: 0.9, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.5, ease: 'power3.out' });
    }
    function close(){
      modal.classList.remove('open');
      lenis.start();
    }
    items.forEach(it => {
      it.addEventListener('click', ()=>{
        const img = it.querySelector('img');
        if(img) open(img.getAttribute('src'), img.getAttribute('alt'));
      });
    });
    if(closeBtn) closeBtn.addEventListener('click', close);
    modal.addEventListener('click', (e)=>{ if(e.target === modal) close(); });
    document.addEventListener('keydown', (e)=>{ if(e.key === 'Escape' && modal.classList.contains('open')) close(); });
  }

})();
